    fn print_header(
        &mut self,
        handle: &mut OutputHandle,
        input: &OpenedInput,
        add_header_padding: bool,
    ) -> Result<()> {
        let term_width = self.config.term_width;
        let wrapping_mode = self.config.wrapping_mode;
        let show_nonprintable = self.config.show_nonprintable;
        let show_filename = self
            .config
            .style_components
            .0
            .contains(&StyleComponent::HeaderFilename);
        let show_filesize = self
            .config
            .style_components
            .0
            .contains(&StyleComponent::HeaderFilesize);
        let show_grid = self.config.style_components.0.contains(&StyleComponent::Grid);
        let show_rule = self.config.style_components.0.contains(&StyleComponent::Rule);
        let show_header = show_filename || show_filesize;

        let mut decoration_panel = 0usize;
        let decoration_count = self.decorations.len();
        for (index, deco) in self.decorations.iter().enumerate() {
            if show_grid && decoration_count > 1 && index + 1 == decoration_count {
                continue;
            }
            decoration_panel += deco.width() + 1;
        }
        if decoration_panel != self.panel_width {
            decoration_panel = self.panel_width;
        }

        if add_header_padding && show_rule {
            writeln!(
                handle,
                "{}",
                self.colors.rule.paint("─".repeat(term_width))
            )?;
        }

        if !show_header {
            if self.content_type == Some(ContentType::BINARY) && !show_nonprintable {
                let summary = match &input.description.summary {
                    Some(summary) => summary.clone(),
                    None => match &input.description.kind {
                        Some(kind) => {
                            format!("{} '{}'", kind.to_lowercase(), input.description.name)
                        }
                        None => input.description.name.clone(),
                    },
                };
                writeln!(
                    handle,
                    "{}: Binary content from {} will not be printed to the terminal \
                     (but will be present if the output of 'bat' is piped). You can use 'bat -A' \
                     to show the binary file contents.",
                    Yellow.paint("[bat warning]"),
                    summary,
                )?;
            } else if show_grid {
                match wrapping_mode {
                    WrappingMode::Character => {
                        if decoration_panel == 0 {
                            if term_width > 0 {
                                let mut line = String::new();
                                let mut filled = 0usize;
                                while filled < term_width {
                                    line.push('─');
                                    filled += 1;
                                }
                                writeln!(handle, "{}", self.colors.grid.paint(line))?;
                            } else {
                                writeln!(handle)?;
                            }
                        } else {
                            let hline = "─".repeat(term_width - (decoration_panel + 1));
                            let hline = format!(
                                "{}{}{}",
                                "─".repeat(decoration_panel),
                                '┬',
                                hline
                            );
                            writeln!(handle, "{}", self.colors.grid.paint(hline))?;
                        }
                    }
                    WrappingMode::NoWrapping(_) => {
                        if decoration_panel == 0 {
                            writeln!(
                                handle,
                                "{}",
                                self.colors.grid.paint("─".repeat(term_width))
                            )?;
                        } else {
                            let hline = "─".repeat(term_width - (decoration_panel + 1));
                            let hline = format!(
                                "{}{}{}",
                                "─".repeat(decoration_panel),
                                '┬',
                                hline
                            );
                            writeln!(handle, "{}", self.colors.grid.paint(hline))?;
                        }
                    }
                }
            }
            return Ok(());
        }

